import { ACCENTS, createTemplateConfig, generateComponent, createEvidenceReport } from './core.mjs';
import { createHistory, recordEdit, undoHistory, redoHistory, serializeProject, parseProject, createUnifiedDiff, parseWorkspaceRequest } from './studio-core.mjs';

export function initStudio(api){
  const $=s=>document.querySelector(s),bench=$('.workbench'),tabs=$('.workspace-tabs');
  bench.classList.add('enhanced-workbench');
  let history=createHistory(api.getConfig()),checkpoint=api.initialCheckpoint||createTemplateConfig('welcome'),codeMode='source',codeFile='component',opener=null,runs=[];
  try{if(!api.initialCheckpoint){const c=JSON.parse(localStorage.getItem('bn-checkpoint-v1'));if(c&&typeof c==='object'&&!Array.isArray(c))checkpoint=createHistory(c).present;}const r=JSON.parse(localStorage.getItem('bn-runs-v1'));if(Array.isArray(r))runs=r.filter(x=>x?.kind==='Blue Nebula browser demo evidence'&&Array.isArray(x.checks)&&Number.isFinite(x.summary?.passed)).slice(0,12);}catch{}
  const host=document.createElement('div');host.className='studio-workspace-shell';const placeholder=document.createComment('Live workspace returns here');tabs.before(placeholder,host);host.append(tabs,bench);
  const dialog=document.createElement('dialog');dialog.className='studio-dialog';dialog.id='studio-dialog';dialog.setAttribute('aria-labelledby','studio-title');
  dialog.innerHTML=`<header class="studio-header"><div class="studio-brand"><span>◉</span><div><b id="studio-title">Next chapter</b><small>BROWSER WORKSPACE / INTERACTIVE CONCEPT</small></div></div><span class="studio-notification" role="status" aria-live="polite">Your ideas have room to grow.</span><div class="studio-header-actions"><button data-studio-import>Import project ↑</button><button data-studio-export>Export project ↓</button><button class="studio-close" aria-label="Close full-screen workspace">×</button></div></header><div class="studio-body"></div><input id="project-import" type="file" accept=".json,application/json" hidden>`;
  document.body.append(dialog);
  $('.workbench-title').insertAdjacentHTML('beforeend','<button class="expand-workspace" aria-label="Open full-screen workspace" title="Open full-screen workspace">Expand ↗</button>');
  $('.workbench-live').innerHTML='<i class="status-dot"></i><span id="save-state">Browser-local concept</span>';
  const toolbar=$('#panel-canvas .panel-toolbar');toolbar.firstElementChild.innerHTML='<label class="template-label"><span>SCREEN</span><select id="screen-template" aria-label="Screen template"><option value="welcome">Welcome screen</option><option value="dashboard">Project dashboard</option><option value="settings">Workspace settings</option></select></label>';
  $('.canvas-toolset').insertAdjacentHTML('afterbegin','<button id="history-undo" aria-label="Undo last canvas change" title="Undo last change">↶</button><button id="history-redo" aria-label="Redo canvas change" title="Redo change">↷</button><button class="inspector-toggle" aria-label="Toggle design properties" aria-expanded="false">Properties ⚙</button>');
  const inspector=$('.canvas-inspector');inspector.querySelector('.inspector-title').innerHTML='SCREEN PROPERTIES <span>⌘</span>';
  inspector.querySelector('.inspector-note').remove();inspector.querySelector('.subtle-button').remove();
  inspector.insertAdjacentHTML('beforeend','<label for="card-description">Supporting text</label><textarea id="card-description" maxlength="160" rows="2"></textarea><label for="card-action-label">Action label</label><input id="card-action-label" maxlength="40"><label for="card-radius">Corner radius <output id="radius-output">16 px</output></label><input id="card-radius" type="range" min="0" max="32" step="4" value="16"><div class="inspector-settings" hidden><span>EXAMPLE PREFERENCES</span><label><input id="setting-local" type="checkbox"> Local-only routing</label><label><input id="setting-notifications" type="checkbox"> Activity notifications</label></div><div class="inspector-tools"><button id="save-checkpoint">Save checkpoint ◇</button><button id="reset-screen">Reset this screen ↶</button></div>');
  $('#design-card>p').id='card-description-preview';$('#card-open').insertAdjacentHTML('beforebegin','<div id="template-preview"></div>');
  $('#panel-code .panel-toolbar').firstElementChild.innerHTML='<label class="generated-file-label"><span class="file-icon">{ }</span><select id="code-file" aria-label="Generated file"><option value="component">WorkspaceScreen.jsx</option><option value="tokens">design-tokens.json</option><option value="project">project.json</option></select></label>';
  $('#panel-code .panel-toolbar').insertAdjacentHTML('afterend','<div class="code-view-controls"><div role="group" aria-label="Code view"><button data-code-mode="source" aria-pressed="true">Source</button><button data-code-mode="changes" aria-pressed="false">Changes <span id="change-indicator">0</span></button></div><span id="checkpoint-state">Compared with saved checkpoint</span><button id="save-code-checkpoint">Save checkpoint ◇</button></div>');
  const prompt=$('.demo-command>div');prompt.className='prompt-editor';prompt.innerHTML='<label for="workflow-prompt">TRY A GUIDED WORKFLOW</label><input id="workflow-prompt" maxlength="150" value="Build a welcome screen using our project conventions."><div class="prompt-presets"><span>TRY:</span><button data-prompt="welcome">Welcome screen</button><button data-prompt="dashboard">Dashboard</button><button data-prompt="settings">Settings</button><small>Scripted local demo · no AI calls</small></div>';
  $('#panel-evaluation .toolbar-actions').insertAdjacentHTML('afterbegin','<button id="run-history">Run history <span id="run-history-count">0</span></button>');
  const stage=$('.canvas-stage');
  function commit(patch){api.setConfig({...api.getConfig(),...patch});}
  function persist(){localStorage.setItem('bn-project-v1',serializeProject(api.getConfig(),checkpoint));}
  function saveCheckpoint(){checkpoint={...api.getConfig()};try{persist();api.toast('Checkpoint saved in this browser.');}catch{api.toast('Checkpoint kept for this session; browser storage is unavailable.');}render();}
  function getCode(){const c=api.getConfig();if(codeMode==='changes')return createUnifiedDiff(generateComponent(checkpoint),generateComponent(c));if(codeFile==='tokens')return JSON.stringify({colors:ACCENTS,spacing:c.gap,radius:c.radius},null,2);if(codeFile==='project')return serializeProject(c,checkpoint);return generateComponent(c);}
  function getFilename(){return codeMode==='changes'?'WorkspaceScreen.patch':codeFile==='tokens'?'design-tokens.json':codeFile==='project'?'Blue-Nebula-Project.json':'WorkspaceScreen.jsx';}
  function render(){
    const focusedPreview=document.activeElement?.id;
    const c=api.getConfig();$('#screen-template').value=c.template;
    for(const [id,value] of [['card-description',c.description],['card-action-label',c.buttonLabel],['card-radius',c.radius]])if($( '#'+id).value!==String(value))$('#'+id).value=value;
    $('#radius-output').textContent=`${c.radius} px`;$('#design-card').style.borderRadius=`${c.radius}px`;$('#card-description-preview').textContent=c.description;
    $('#card-open').replaceChildren(document.createTextNode(c.buttonLabel||'Add an action label'),Object.assign(document.createElement('span'),{textContent:'↗'}));
    $('.frame-label').firstChild.textContent=c.template.toUpperCase()+' / SCREEN ';$('.inspector-settings').hidden=c.template!=='settings';$('#setting-local').checked=c.localOnly;$('#setting-notifications').checked=c.notifications;
    $('#template-preview').innerHTML=c.template==='dashboard'?'<div class="sample-metrics"><div><small>PROJECTS</small><b>3</b></div><div><small>OPEN TASKS</small><b>7</b></div><div><small>DECISIONS</small><b>4</b></div></div><div class="sample-chart" aria-label="Illustrative activity chart"><i style="--bar:35%"></i><i style="--bar:58%"></i><i style="--bar:43%"></i><i style="--bar:76%"></i><i style="--bar:64%"></i><i style="--bar:93%"></i><i style="--bar:80%"></i></div><span class="sample-data-label">ILLUSTRATIVE PROJECT DATA</span>':c.template==='settings'?'<div class="sample-preferences"><label><span>Local-only routing<small>Example preference</small></span><input id="preview-local" type="checkbox" '+(c.localOnly?'checked':'')+'></label><label><span>Activity notifications<small>Example preference</small></span><input id="preview-notifications" type="checkbox" '+(c.notifications?'checked':'')+'></label></div>':'';
    $('#preview-local')?.addEventListener('change',e=>commit({localOnly:e.target.checked}));$('#preview-notifications')?.addEventListener('change',e=>commit({notifications:e.target.checked}));
    if(focusedPreview?.startsWith('preview-'))document.getElementById(focusedPreview)?.focus();
    $('#history-undo').disabled=!history.past.length;$('#history-redo').disabled=!history.future.length;
    const patch=createUnifiedDiff(generateComponent(checkpoint),generateComponent(c));$('#change-indicator').textContent=patch?'●':'0';$('#checkpoint-state').textContent=patch?'Uncheckpointed changes':'Matches saved checkpoint';
    $('#code-file').disabled=codeMode==='changes';const text=getCode(),code=$('#generated-code');code.replaceChildren();
    if(codeMode==='changes'&&text){text.split('\n').forEach(line=>{const span=document.createElement('span');span.className=line.startsWith('+')&&!line.startsWith('+++')?'diff-added':line.startsWith('-')&&!line.startsWith('---')?'diff-removed':line.startsWith('@@')?'diff-hunk':'';span.textContent=line+'\n';code.append(span);});}else code.textContent=text||(codeMode==='changes'?'No changes from the saved checkpoint.':'');
    $('.code-lines').textContent=codeMode==='source'?text.split('\n').map((_,i)=>i+1).join('\n'):'';$('#download-code').disabled=codeMode==='changes'&&!patch;$('#copy-code').disabled=codeMode==='changes'&&!patch;
    $('#run-history-count').textContent=runs.length;
  }
  function open(options={},trigger=document.activeElement){
    if(options.template){api.cancelWorkflow();api.setConfig({...createTemplateConfig(options.template),...(options.accent?{accent:options.accent}:{})});}
    if(options.tab)api.setTab(options.tab);
    if(dialog.open)return;
    const menu=trigger?.closest?.('.nav-dropdown'),mobile=trigger?.closest?.('#mobile-nav');opener=menu?.querySelector('.nav-trigger')||(mobile?$('.mobile-toggle'):trigger);api.closeMenus();$('.studio-body').append(host);dialog.showModal();document.body.classList.add('studio-open');document.dispatchEvent(new CustomEvent('bn:workspace-visibility',{detail:{open:true}}));$('.studio-close').focus();
  }
  dialog.addEventListener('close',()=>{placeholder.after(host);document.body.classList.remove('studio-open');document.dispatchEvent(new CustomEvent('bn:workspace-visibility',{detail:{open:false}}));if(opener?.isConnected&&opener.getClientRects().length&&!opener.closest('[inert]'))opener.focus();else $('.nav-cta').focus();});
  $('.studio-close').addEventListener('click',()=>dialog.close());$('.expand-workspace').addEventListener('click',e=>open({},e.currentTarget));
  document.querySelectorAll('[data-open-studio]').forEach(b=>b.addEventListener('click',e=>open({tab:'canvas'},e.currentTarget)));
  document.addEventListener('bn:open-workspace',e=>open(e.detail,e.detail?.trigger||document.activeElement));
  $('#screen-template').addEventListener('change',e=>{api.cancelWorkflow();api.setConfig(createTemplateConfig(e.target.value));});
  $('#card-description').addEventListener('input',e=>commit({description:e.target.value}));$('#card-action-label').addEventListener('input',e=>commit({buttonLabel:e.target.value}));$('#card-radius').addEventListener('input',e=>commit({radius:e.target.value}));
  $('#setting-local').addEventListener('change',e=>commit({localOnly:e.target.checked}));$('#setting-notifications').addEventListener('change',e=>commit({notifications:e.target.checked}));
  $('#history-undo').addEventListener('click',()=>{history=undoHistory(history);api.setConfig(history.present,false);});$('#history-redo').addEventListener('click',()=>{history=redoHistory(history);api.setConfig(history.present,false);});
  $('#reset-screen').addEventListener('click',()=>api.setConfig(createTemplateConfig(api.getConfig().template)));$('#save-checkpoint').addEventListener('click',saveCheckpoint);$('#save-code-checkpoint').addEventListener('click',saveCheckpoint);
  $('.inspector-toggle').addEventListener('click',e=>{const expanded=bench.classList.toggle('properties-open');e.currentTarget.setAttribute('aria-expanded',expanded);});
  document.querySelectorAll('[data-code-mode]').forEach(b=>b.addEventListener('click',()=>{codeMode=b.dataset.codeMode;document.querySelectorAll('[data-code-mode]').forEach(x=>x.setAttribute('aria-pressed',x===b));render();}));$('#code-file').addEventListener('change',e=>{codeFile=e.target.value;render();});
  document.querySelectorAll('[data-prompt]').forEach(b=>b.addEventListener('click',()=>{$('#workflow-prompt').value=`Build a ${b.dataset.prompt} screen using our project conventions.`;$('#workflow-prompt').focus();}));
  $('[data-studio-export]').addEventListener('click',()=>{api.download('Blue-Nebula-Project.json',serializeProject(api.getConfig(),checkpoint),'application/json');api.toast('Current screen and checkpoint exported.');});
  const fileInput=$('#project-import');
  function importText(text){const data=parseProject(text);api.cancelWorkflow();checkpoint=data.checkpoint;api.setConfig(data.configuration);api.setTab('canvas');api.closeResource();api.toast('Project imported. The previous screen is available through Undo.');}
  $('[data-studio-import]').addEventListener('click',()=>{const fragment=document.createElement('div');fragment.className='project-import-panel';fragment.innerHTML='<h2 id="dialog-title">Bring your project back.</h2><p>Choose a Blue Nebula project file, or paste its exported JSON below. The screen and checkpoint stay together. Nothing is uploaded.</p><label for="project-paste">PROJECT JSON</label><textarea id="project-paste" spellcheck="false" maxlength="65536" placeholder="Paste a version 1 Blue Nebula project…"></textarea><p id="project-import-error" role="alert"></p><div class="project-import-actions"><button id="choose-project-file">Choose a JSON file ↑</button><button id="import-project-text" class="button button-small">Import this project ↗</button></div>';fragment.append(fileInput);fragment.querySelector('#choose-project-file').addEventListener('click',()=>fileInput.click());fragment.querySelector('#import-project-text').addEventListener('click',()=>{try{importText($('#project-paste').value);}catch(error){$('#project-import-error').textContent=error.message;}});api.showNode(fragment);});
  $('#resource-dialog').addEventListener('close',()=>{if(fileInput.parentElement!==dialog)dialog.append(fileInput);});
  fileInput.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>65536)throw Error('Choose a project smaller than 64 KB.');importText(await file.text());}catch(error){if($('#project-import-error'))$('#project-import-error').textContent=error.message;else api.toast(error.message);}finally{e.target.value='';}});
  document.addEventListener('keydown',e=>{if(!dialog.open||!e.ctrlKey&&!e.metaKey||e.target.matches('input,textarea,select'))return;if(e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('#history-redo'):$('#history-undo')).click();}});
  $('#run-history').addEventListener('click',()=>{const fragment=document.createDocumentFragment(),title=document.createElement('h2');title.id='dialog-title';title.textContent='Evidence from your session';fragment.append(title);if(!runs.length){const p=document.createElement('p');p.textContent='Run the fixture checks to record a result. Each run retains its own configuration and observed outcomes.';fragment.append(p);}runs.forEach((report,i)=>{const row=document.createElement('div');row.className='evidence-history-row';const text=document.createElement('p');text.textContent=`${report.summary.passed}/${report.summary.total} checks · ${report.configuration?.title||'Untitled screen'} · ${new Date(report.generatedAt).toLocaleTimeString()}`;const button=document.createElement('button');button.textContent='Download JSON ↓';button.addEventListener('click',()=>api.download(`Blue-Nebula-Evidence-${i+1}.json`,JSON.stringify(report,null,2),'application/json'));row.append(text,button);fragment.append(row);});api.showNode(fragment);});
  return {render,open,getCode,getFilename,persist,record(input){history=recordEdit(history,input);},notify(message){if(dialog.open)$('.studio-notification').textContent=message;},recordRun(){runs.unshift(createEvidenceReport(api.getConfig()));runs=runs.slice(0,12);try{localStorage.setItem('bn-runs-v1',JSON.stringify(runs));}catch{}render();},prepareWorkflow(){const template=parseWorkspaceRequest($('#workflow-prompt').value);if(!template){api.toast('This local demo supports welcome, dashboard, or settings screens. Try one of the suggested prompts.');return false;}if(template!==api.getConfig().template)api.setConfig(createTemplateConfig(template));return true;}};
}
